#!/usr/bin/env python3\n"""Static health checks for the MyTasks bot.\n\nThis is intentionally read-only: it reports structural debt without changing\nthe application. The duplicate-definition report is important because bot.py\ncurrently uses a legacy-wrapper chain where later definitions override earlier\nones.\n"""\nfrom __future__ import annotations\n\nimport ast\nimport collections\nimport pathlib\nimport sys\n\n\ndef inspect_file(path: pathlib.Path) -> int:\n    source = path.read_text(encoding="utf-8")\n    tree = ast.parse(source, filename=str(path))\n    definitions: dict[str, list[int]] = collections.defaultdict(list)\n    for node in ast.walk(tree):\n        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\n            definitions[node.name].append(node.lineno)\n    duplicates = {name: lines for name, lines in definitions.items() if len(lines) > 1}\n    print(f"{path}: {len(source.splitlines())} lines, {len(definitions)} named definitions")\n    if duplicates:\n        print(f"  duplicate definitions: {len(duplicates)}")\n        for name, lines in sorted(duplicates.items()):\n            print(f"    {name}: {', '.join(map(str, lines))}")\n    else:\n        print("  duplicate definitions: 0")\n    return len(duplicates)\n\n\ndef main() -> int:\n    root = pathlib.Path(__file__).resolve().parents[1]\n    total = inspect_file(root / "bot.py")\n    total += inspect_file(root / "database.py")\n    total += inspect_file(root / "config.py")\n    print(f"\nTotal duplicate-definition groups: {total}")\n    # Reporting is non-blocking during the migration; CI still blocks on syntax\n    # and undefined-name errors through Ruff.\n    return 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n